package com.fifotech.task.controller;
import com.fifotech.task.domain.User;import com.fifotech.task.dto.ApiDtos.*;import com.fifotech.task.service.UserService;import jakarta.validation.Valid;import org.springframework.data.domain.Page;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/users") public class UserController {private final UserService users;public UserController(UserService users){this.users=users;}@GetMapping("/team") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") public java.util.List<UserResponse> team(@AuthenticationPrincipal User actor){return users.team(actor);}@GetMapping @PreAuthorize("hasRole('ADMIN')") public Page<UserResponse> list(@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size){return users.list(search,page,size);}@GetMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public UserResponse get(@PathVariable Long id){return users.get(id);}@PostMapping @PreAuthorize("hasRole('ADMIN')") public UserResponse create(@Valid @RequestBody UserRequest r){return users.create(r);}@PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public UserResponse update(@PathVariable Long id,@Valid @RequestBody UserRequest r){return users.update(id,r);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public void delete(@PathVariable Long id){users.delete(id);}}
